CREATE TABLE price_records (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, product_id integer NOT NULL, price real NOT NULL, price_type text DEFAULT '促销价' NOT NULL, promotion_tag text DEFAULT '' NOT NULL, store text DEFAULT '' NOT NULL, recorded_at text NOT NULL, note text DEFAULT '' NOT NULL, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE products (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, name text NOT NULL, brand text DEFAULT '' NOT NULL, category text DEFAULT '其他' NOT NULL, quantity real NOT NULL, unit text NOT NULL, protein real DEFAULT 0 NOT NULL, fat real DEFAULT 0 NOT NULL, carbohydrate real DEFAULT 0 NOT NULL, sugar real DEFAULT 0 NOT NULL, energy real DEFAULT 0 NOT NULL, target_unit_price real, created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE promotion_tags (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, name text NOT NULL, color text DEFAULT 'amber' NOT NULL);
CREATE UNIQUE INDEX promotion_tags_name_unique ON promotion_tags(name);